    {
      "statement": "Under UAE Federal Law Executive Regulations, disclosing a patient's health information to any party without the consent of the patient or their legal representative is legally prohibited, unless permitted by applicable legislation in force in the UAE.",
      "citations": [
        "uae-health-ict-exec-reg-2020#0007"
      ]
    },
    {
      "statement": "Under Dubai Health Authority (DHA) Policy, sharing health information between non-affiliated entities in the UAE via Health Information Exchanges (NABIDH, Malaffi, Riayati) requires patient consent.",
      "citations": [
        "dha-health-info-sharing-2024#0015"
      ]
    },
    {
      "statement": "Under DHA Standards, patient consent for accessing health information systems remains valid for one year following the patient's last health encounter, unless explicitly revoked.",
      "citations": [
        "dha-consent-access-standard-2025#0017"
      ]
    },
    {
      "statement": "Under DHA Standards, patients must be informed of the potential consequences of not sharing health information and retain the right to withdraw consent and opt out, though withdrawal does not affect prior lawful access or incorporation of information into facility records.",
      "citations": [
        "dha-consent-access-standard-2025#0018"
      ]
    },
    {
      "statement": "Under Abu Dhabi Department of Health (DoH) Policy, healthcare facilities are mandated to share patient data with the Abu Dhabi Health Information Exchange (Malaffi) under universal participation goals and must seek patient consent by incorporating standard consent wording into healthcare facility consent forms.",
      "citations": [
        "doh-hie-policy-2020#0021",
        "doh-hie-policy-2020#0022"
      ]
    }
  ],
